"""Golden generated by executing origin/main before this change; no network."""
import json
from datetime import datetime
from pathlib import Path
from types import SimpleNamespace

import pytest

from quant_platform_kit.common.operational_notification_localization import (
    format_operational_alert, format_operational_heartbeat_status, format_receipt_alert, format_sgt_time,
)
from quant_platform_kit.notifications import digest_routing
from quant_platform_kit.notifications.events import NotificationPublisher, RenderedNotification
from quant_platform_kit.notifications.unified_contract import NotificationEvent, route_notification_event

FLAGS = ["IBKR_UNIFIED_NOTIFICATION_ENABLED", "SCHWAB_UNIFIED_NOTIFICATION_ENABLED",
         "LONGBRIDGE_UNIFIED_NOTIFICATION_ENABLED", "BINANCE_UNIFIED_NOTIFICATION_ENABLED",
         "FIRSTRADE_UNIFIED_NOTIFICATION_ENABLED", "QRS_UNIFIED_NOTIFICATION_ENABLED"]
GOLDEN = json.loads((Path(__file__).parent / 'fixtures/unified_notification_legacy_main.json').read_text())


@pytest.mark.parametrize('flag_value', [None, 'false', '', 'invalid'])
@pytest.mark.parametrize('mode', ['immediate', 'daily_digest', 'invalid'])
@pytest.mark.parametrize('routine_order', [False, True])
def test_flags_off_existing_entrypoints_sends_and_calls_match_main(monkeypatch, flag_value, mode, routine_order):
    for flag in FLAGS:
        if flag_value is None:
            monkeypatch.delenv(flag, raising=False)
        else:
            monkeypatch.setenv(flag, flag_value)
    monkeypatch.delenv('QSL_DIGEST_ROUTINE_ORDERS', raising=False)
    monkeypatch.setenv('QSL_ROUTINE_NOTIFICATION_MODE', mode)
    report, calls = {}, []
    def sender(runtime, report, text):
        calls.append([runtime, dict(report), text])
        return 'sender-result'
    result = digest_routing.routine_notification(sender, 'runtime', report, 'existing text', routine_order=routine_order)
    signals = [SimpleNamespace(canonical_route='watch', suggested_action='observe'), SimpleNamespace(canonical_route='trade', suggested_action='buy')]
    actual = {
        'calls': calls, 'report': report, 'result': result,
        'defer_healthy': digest_routing.defer_routine_cycle_to_digest({'execution_status': 'no_action'}, submitted_order_count=0),
        'signals': [s.canonical_route for s in digest_routing.immediate_plugin_signals(signals)],
    }
    assert actual == GOLDEN['observations'][f'{mode}:{routine_order}']


@pytest.mark.parametrize('locale', ['zh', 'en'])
def test_existing_renderers_and_publisher_match_main_byte_for_byte(monkeypatch, locale):
    for flag in FLAGS:
        monkeypatch.delenv(flag, raising=False)
    message = format_operational_alert(locale=locale, alert_type='execution_report_heartbeat', name='runtime',
        context={'lookback_hours': 36}, issues=['existing diagnostic'], recent_reports=['original report'],
        technical_details=['original detail'], latest_runtime_run=['original run'], workflow_url='https://example.test/run/1')
    expected = GOLDEN['observations'][f'alert:{locale}']
    assert message.encode() == expected.encode()
    heartbeat = format_operational_heartbeat_status(locale=locale, name='runtime', detail='existing detail')
    assert heartbeat.encode() == GOLDEN['observations'][f'heartbeat:{locale}'].encode()
    calls = []
    publisher = NotificationPublisher(log_message=lambda text: calls.append(('log', text)),
                                      send_message=lambda text: calls.append(('send', text)) or True)
    assert publisher.publish(RenderedNotification(message, heartbeat))
    assert calls == [('log', expected), ('send', heartbeat)]


def test_new_dispatcher_off_calls_only_unchanged_legacy_callback():
    stamp = datetime.fromisoformat('2026-10-17T06:00:00+08:00')
    calls = []
    fact = NotificationEvent('routine_cycle', stamp)
    result = route_notification_event(fact, env={}, flag_key=FLAGS[0],
        persist_candidate=lambda _: pytest.fail('candidate write while OFF'),
        immediate=lambda: pytest.fail('new immediate while OFF'), legacy=lambda: calls.append('legacy') or 42)
    assert calls == ['legacy'] and result.route == 'legacy' and result.result == 42


@pytest.mark.parametrize('locale', ['zh', 'en'])
def test_receipt_categories_localized_sgt_one_blocked_five_time_skips(locale):
    stamp = datetime.fromisoformat('2026-10-17T00:35:20+00:00')
    message = format_receipt_alert(locale=locale,
        categories={'strategy_risk_rejected': 1, 'skipped_before_due': 3, 'skipped_outside_window': 2},
        observed_at=stamp, due_at=datetime.fromisoformat('2026-10-16T19:45:00+00:00'), orders_submitted_count=0,
        run_url='https://example.test/run/1?account=private#raw')
    assert '2026-10-17 08:35:20' in message and '2026-10-17 03:45:00' in message
    assert all(raw not in message for raw in ['gs://', 'account=', 'private', 'strategy_risk_rejected', 'skipped_before_due'])
    if locale == 'zh':
        assert '本轮已运行但被风控拦截：1 份' in message
        assert '已跳过：3 份' in message and '已跳过：2 份' in message
        assert '本轮提交订单：0' in message and '运行记录：' in message
        assert 'SGT' not in message and 'Unknown' not in message
    else:
        assert 'blocked by strategy risk checks: 1 report(s)' in message
        assert 'Orders submitted this run: 0' in message
        assert not any('\u4e00' <= c <= '\u9fff' for c in message)


def test_receipt_unknown_values_do_not_echo_raw_uris_accounts_or_fill_zeros():
    message = format_receipt_alert(locale='zh', categories={'gs://private/account': None})
    assert '回执分类未知：未知' in message and '本轮提交订单：未知' in message
    assert 'gs://' not in message and 'account' not in message
    assert '：0' not in message
    with pytest.raises(ValueError):
        format_sgt_time(datetime(2026, 10, 17))
    with pytest.raises(ValueError):
        format_receipt_alert(locale='en', categories={}, run_url='gs://private/account')
